// Do not edit this file as it will be overwritten if HAMR codegen is rerun

use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

/** I-Assm: Integration constraint on FirewallTx's incoming event data port EthernetFramesTxIn
  *
  * assume TxIn_IPv4OrARP
  *   The TxFirewall receives only IPv4 or ARP frames.
  */
pub fn I_Assm_EthernetFramesTxIn(EthernetFramesTxIn: SW::StructuredEthernetMessage_i) -> bool
{
  GumboLib::txExpected(EthernetFramesTxIn)
}

/** I-Assm: Integration constraint on FirewallTx's incoming event data port EthernetFramesTxIn
  *
  * assume TxIn_IPv4OrARP
  *   The TxFirewall receives only IPv4 or ARP frames.
  */
pub fn I_Assm_Guard_EthernetFramesTxIn(EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    EthernetFramesTxIn.is_some(),
    I_Assm_EthernetFramesTxIn(EthernetFramesTxIn.unwrap())
  )
}

/** I-Guar: Integration constraint on FirewallTx's outgoing event data port EthernetFramesTxOut
  *
  * guarantee TxOut_OnlyPermitted
  *  Only non-malformed IPv4 or ARP frames leave the TxFirewall.
  */
pub fn I_Guar_EthernetFramesTxOut(EthernetFramesTxOut: SW::StructuredEthernetMessage_i) -> bool
{
  !(GumboLib::isMalformedFrame(EthernetFramesTxOut)) & GumboLib::txExpected(EthernetFramesTxOut)
}

/** I-Guar: Integration constraint on FirewallTx's outgoing event data port EthernetFramesTxOut
  *
  * guarantee TxOut_OnlyPermitted
  *  Only non-malformed IPv4 or ARP frames leave the TxFirewall.
  */
pub fn I_Guar_Guard_EthernetFramesTxOut(EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    EthernetFramesTxOut.is_some(),
    I_Guar_EthernetFramesTxOut(EthernetFramesTxOut.unwrap())
  )
}

/** Initialize EntryPointContract
  *
  * guarantee CR01_Tx_Init
  *   FirewallTx_Req_Init: attack status DataPort initialized to OK.
  * @param api_AttackStatusTx outgoing data port
  */
pub fn initialize_CR01_Tx_Init(api_AttackStatusTx: SW::AttackStatus) -> bool
{
  api_AttackStatusTx == SW::AttackStatus::OK
}

/** IEP-Guar: Initialize Entrypoint for FirewallTx
  *
  * @param api_EthernetFramesTxOut outgoing event data port
  * @param api_AttackStatusTx outgoing data port
  */
pub fn initialize_IEP_Guar(
  api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>,
  api_AttackStatusTx: SW::AttackStatus) -> bool
{
  initialize_CR01_Tx_Init(api_AttackStatusTx)
}

/** IEP-Post: Initialize Entrypoint Post-Condition
  *
  * @param api_EthernetFramesTxOut outgoing event data port
  * @param api_AttackStatusTx outgoing data port
  */
pub fn initialize_IEP_Post(
  api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>,
  api_AttackStatusTx: SW::AttackStatus) -> bool
{
  // I-Guar-Guard: Integration constraints for FirewallTx's outgoing ports"
  I_Guar_Guard_EthernetFramesTxOut(api_EthernetFramesTxOut)&& 

  initialize_IEP_Guar(api_EthernetFramesTxOut, api_AttackStatusTx)
}

/** CEP-Pre: Compute Entrypoint Pre-Condition for FirewallTx
  *
  * @param api_EthernetFramesTxIn incoming event data port
  * @param api_CurrentMode incoming data port
  */
pub fn compute_CEP_Pre(
  api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
  api_CurrentMode: SW::Mode) -> bool
{
  // I-Assm-Guard: Integration constraints for FirewallTx's incoming ports
  let r0: bool = I_Assm_Guard_EthernetFramesTxIn(api_EthernetFramesTxIn);

  return r0;
}

/** Compute Entrypoint Contract
  *
  * guarantee RC_INSPECTA_00_HLR_7
  *   2.1 firewall: copy out TxIn arp frame (RC_INSPECTA_00-HLR-7; revised CR-01: applies in Normal mode only) In Normal mode, if the firewall gets a wellformed Arp frame from TxIn, the firewall shall copy the frame to TxOut.
  * @param api_EthernetFramesTxIn incoming event data port
  * @param api_CurrentMode incoming data port
  * @param api_EthernetFramesTxOut outgoing event data port
  */
pub fn compute_spec_RC_INSPECTA_00_HLR_7_guarantee(
  api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
  api_CurrentMode: SW::Mode,
  api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    api_EthernetFramesTxIn.is_some(),
    impliesL!(
      (api_CurrentMode == SW::Mode::Normal) &
        !(GumboLib::isMalformedFrame(api_EthernetFramesTxIn.unwrap())) &
        GumboLib::isARP(api_EthernetFramesTxIn.unwrap()),
      api_EthernetFramesTxOut.is_some() &&
        (api_EthernetFramesTxIn.unwrap() == api_EthernetFramesTxOut.unwrap())))
}

/** Compute Entrypoint Contract
  *
  * guarantee RC_INSPECTA_00_HLR_12
  *   2.2 firewall: copy out TxIn ipv4 frame (RC_INSPECTA_00-HLR-12; revised CR-01: applies in Normal mode only) In Normal mode, if the firewall gets a wellformed IPv4 frame from TxIn, the firewall shall copy the frame to TxOut.
  * @param api_EthernetFramesTxIn incoming event data port
  * @param api_CurrentMode incoming data port
  * @param api_EthernetFramesTxOut outgoing event data port
  */
pub fn compute_spec_RC_INSPECTA_00_HLR_12_guarantee(
  api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
  api_CurrentMode: SW::Mode,
  api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    api_EthernetFramesTxIn.is_some(),
    impliesL!(
      (api_CurrentMode == SW::Mode::Normal) &
        !(GumboLib::isMalformedFrame(api_EthernetFramesTxIn.unwrap())) &
        GumboLib::isIPV4(api_EthernetFramesTxIn.unwrap()),
      api_EthernetFramesTxOut.is_some() &&
        (api_EthernetFramesTxIn.unwrap() == api_EthernetFramesTxOut.unwrap())))
}

/** Compute Entrypoint Contract
  *
  * guarantee RC_INSPECTA_00_HLR_14
  *   2.3 firewall: do not copy disallowed frame (RC_INSPECTA_00-HLR-14) If the firewall gets a malformed ARP frame or malformed TCP frame, it should drop the frame.
  * @param api_EthernetFramesTxIn incoming event data port
  * @param api_EthernetFramesTxOut outgoing event data port
  */
pub fn compute_spec_RC_INSPECTA_00_HLR_14_guarantee(
  api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
  api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    api_EthernetFramesTxIn.is_some(),
    impliesL!(
      (!(GumboLib::isIPV4(api_EthernetFramesTxIn.unwrap())) && !(GumboLib::isARP(api_EthernetFramesTxIn.unwrap()))) |
        GumboLib::isMalformedFrame(api_EthernetFramesTxIn.unwrap()),
      api_EthernetFramesTxOut.is_none()))
}

/** Compute Entrypoint Contract
  *
  * guarantee RC_INSPECTA_00_HLR_16
  *   2.4 firewall: no output on empty input (RC_INSPECTA_00-HLR-16) If the firewall gets no input on TxIn, it should produce no output on TxOut
  * @param api_EthernetFramesTxIn incoming event data port
  * @param api_EthernetFramesTxOut outgoing event data port
  */
pub fn compute_spec_RC_INSPECTA_00_HLR_16_guarantee(
  api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
  api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    !(api_EthernetFramesTxIn.is_some()),
    api_EthernetFramesTxOut.is_none())
}

/** Compute Entrypoint Contract
  *
  * guarantee CR01_Tx_ModeGate
  *   FirewallTx_Req_ModeGate (CR-01): in Init and RTL modes, drop every frame — no output regardless of input.
  * @param api_CurrentMode incoming data port
  * @param api_EthernetFramesTxOut outgoing event data port
  */
pub fn compute_spec_CR01_Tx_ModeGate_guarantee(
  api_CurrentMode: SW::Mode,
  api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    !(api_CurrentMode == SW::Mode::Normal),
    api_EthernetFramesTxOut.is_none())
}

/** Compute Entrypoint Contract
  *
  * guarantee CR01_Tx_Detect
  *   FirewallTx_Req_Detect (CR-01): report Attack on any dispatch whose received frame carries the mocked geofence violation (rawMessage byte 0 == 0), OK on every other dispatch; mode-independent, per-dispatch (no latch — persistence is the ModeManager's RTL).
  * @param api_EthernetFramesTxIn incoming event data port
  * @param api_AttackStatusTx outgoing data port
  */
pub fn compute_spec_CR01_Tx_Detect_guarantee(
  api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
  api_AttackStatusTx: SW::AttackStatus) -> bool
{
  (implies!(
    api_EthernetFramesTxIn.is_some() && GumboLib::isGeofenceViolation(api_EthernetFramesTxIn.unwrap()),
    (api_AttackStatusTx == SW::AttackStatus::Attack))) &
    (implies!(
      !(api_EthernetFramesTxIn.is_some()) || !(GumboLib::isGeofenceViolation(api_EthernetFramesTxIn.unwrap())),
      (api_AttackStatusTx == SW::AttackStatus::OK)))
}

/** CEP-T-Guar: Top-level guarantee contracts for FirewallTx's compute entrypoint
  *
  * @param api_EthernetFramesTxIn incoming event data port
  * @param api_CurrentMode incoming data port
  * @param api_EthernetFramesTxOut outgoing event data port
  * @param api_AttackStatusTx outgoing data port
  */
pub fn compute_CEP_T_Guar(
  api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
  api_CurrentMode: SW::Mode,
  api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>,
  api_AttackStatusTx: SW::AttackStatus) -> bool
{
  let r0: bool = compute_spec_RC_INSPECTA_00_HLR_7_guarantee(api_EthernetFramesTxIn, api_CurrentMode, api_EthernetFramesTxOut);
  let r1: bool = compute_spec_RC_INSPECTA_00_HLR_12_guarantee(api_EthernetFramesTxIn, api_CurrentMode, api_EthernetFramesTxOut);
  let r2: bool = compute_spec_RC_INSPECTA_00_HLR_14_guarantee(api_EthernetFramesTxIn, api_EthernetFramesTxOut);
  let r3: bool = compute_spec_RC_INSPECTA_00_HLR_16_guarantee(api_EthernetFramesTxIn, api_EthernetFramesTxOut);
  let r4: bool = compute_spec_CR01_Tx_ModeGate_guarantee(api_CurrentMode, api_EthernetFramesTxOut);
  let r5: bool = compute_spec_CR01_Tx_Detect_guarantee(api_EthernetFramesTxIn, api_AttackStatusTx);

  return r0 && r1 && r2 && r3 && r4 && r5;
}

/** CEP-Post: Compute Entrypoint Post-Condition for FirewallTx
  *
  * @param api_EthernetFramesTxIn incoming event data port
  * @param api_CurrentMode incoming data port
  * @param api_EthernetFramesTxOut outgoing event data port
  * @param api_AttackStatusTx outgoing data port
  */
pub fn compute_CEP_Post(
  api_EthernetFramesTxIn: Option<SW::StructuredEthernetMessage_i>,
  api_CurrentMode: SW::Mode,
  api_EthernetFramesTxOut: Option<SW::StructuredEthernetMessage_i>,
  api_AttackStatusTx: SW::AttackStatus) -> bool
{
  // I-Guar-Guard: Integration constraints for FirewallTx's outgoing ports
  let r0: bool = I_Guar_Guard_EthernetFramesTxOut(api_EthernetFramesTxOut);

  // CEP-Guar: guarantee clauses of FirewallTx's compute entrypoint
  let r1: bool = compute_CEP_T_Guar(api_EthernetFramesTxIn, api_CurrentMode, api_EthernetFramesTxOut, api_AttackStatusTx);

  return r0 && r1;
}
